import React, { useState, useEffect } from 'react';
import './App.css';

// Import components
import Navbar from './components/ui/Navbar';
import Explore from './components/layout/Explore';
import Holdings from './components/layout/Holdings';
import Positions from './components/layout/Positions';
import Orders from './components/layout/Orders';
import WatchlistPage from './components/layout/WatchlistPage';
import Recharge from './components/layout/Recharge';
import StockSearch from './components/trading/StockSearch';
import StockDetails from './components/trading/StockDetails';
import PriceChart from './components/trading/PriceChart';
import TradePanel from './components/trading/TradePanel';
import HoldingsTable from './components/portfolio/HoldingsTable';

const API_URL = 'http://localhost:5000/api';

function App() {
  // Auth state
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  // Trading state
  const [symbol, setSymbol] = useState('RELIANCE');
  const [price, setPrice] = useState(null);
  const [balance, setBalance] = useState(0);
  const [portfolio, setPortfolio] = useState([]);
  const [activeTab, setActiveTab] = useState('explore');

  useEffect(() => {
    if (isLoggedIn) {
      fetchPortfolio();
      fetchPrice();
      const interval = setInterval(() => {
        fetchPortfolio();
        if (activeTab === 'trading') {
          fetchPrice();
        }
      }, 30000);
      return () => clearInterval(interval);
    }
  }, [isLoggedIn, activeTab, symbol]);

  // Auth functions
  const register = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, email, password })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
    } catch (error) {
      setMessage('Error connecting to server. Is Flask running?');
    }
    setLoading(false);
  };

  const login = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ username, password })
      });
      const data = await response.json();
      if (data.message) {
        setIsLoggedIn(true);
        setMessage(`Welcome ${username}!`);
        fetchPortfolio();
        fetchPrice();
      } else {
        setMessage(data.error || 'Login failed');
      }
    } catch (error) {
      setMessage('Error connecting to server. Is Flask running?');
    }
    setLoading(false);
  };

  const logout = async () => {
    await fetch(`${API_URL}/logout`, {
      method: 'POST',
      credentials: 'include'
    });
    setIsLoggedIn(false);
    setMessage('Logged out');
  };

  // Trading functions
  const fetchPrice = async () => {
    if (!symbol) return;
    try {
      const response = await fetch(`${API_URL}/price/${symbol}`);
      const data = await response.json();
      if (data.price) {
        setPrice(data.price);
      }
    } catch (error) {
      console.error('Error fetching price:', error);
    }
  };

  const fetchPortfolio = async () => {
    try {
      const response = await fetch(`${API_URL}/portfolio`, {
        credentials: 'include'
      });
      const data = await response.json();
      if (data.portfolio !== undefined) {
        setPortfolio(data.portfolio || []);
        setBalance(data.balance || 0);
      }
    } catch (error) {
      console.error('Error fetching portfolio:', error);
    }
  };

  const handleBuy = async (quantity) => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/buy`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ symbol, quantity })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchPortfolio();
      }
    } catch (error) {
      setMessage('Error buying stock');
    }
    setLoading(false);
  };

  const handleSell = async (quantity) => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/sell`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ symbol, quantity })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchPortfolio();
      }
    } catch (error) {
      setMessage('Error selling stock');
    }
    setLoading(false);
  };

  const handleSelectStock = (selectedSymbol) => {
    setSymbol(selectedSymbol);
    setActiveTab('trading');
    setTimeout(() => fetchPrice(), 100);
  };

  // Render login/register
  if (!isLoggedIn) {
    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '100vh',
        background: '#0a0e17',
        color: 'white',
        fontFamily: 'Arial'
      }}>
        <div style={{
          background: '#141b2b',
          padding: '40px',
          borderRadius: '12px',
          width: '100%',
          maxWidth: '400px',
          border: '1px solid #2a3a5c'
        }}>
          <h1 style={{ textAlign: 'center', color: '#4CAF50' }}>📈 DemoTrader</h1>
          <p style={{ textAlign: 'center', color: '#4CAF50' }}>🎉 Get ₹1,00,000 FREE!</p>
          
          {message && <div style={{
            padding: '10px',
            margin: '10px 0',
            borderRadius: '6px',
            background: '#1a2332',
            textAlign: 'center'
          }}>{message}</div>}
          
          <h2 style={{ color: '#8a9bb5', fontSize: '18px', marginTop: '20px' }}>Login</h2>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <button
            onClick={login}
            disabled={loading}
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '10px',
              background: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            {loading ? '...' : 'Login'}
          </button>
          
          <h2 style={{ color: '#8a9bb5', fontSize: '18px', marginTop: '20px' }}>Register</h2>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <button
            onClick={register}
            disabled={loading}
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '10px',
              background: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            {loading ? '...' : 'Register & Get ₹1L'}
          </button>
        </div>
      </div>
    );
  }

  // Render dashboard
  const renderContent = () => {
    switch(activeTab) {
      case 'explore':
        return <Explore onSelectStock={handleSelectStock} />;

      case 'holdings':
        return <Holdings portfolio={portfolio} balance={balance} />;

      case 'positions':
        return <Positions />;

      case 'orders':
        return <Orders />;

      case 'watchlist':
        return <WatchlistPage onSelectStock={handleSelectStock} />;

      case 'recharge':
        return (
          <Recharge 
            balance={balance}
            onRecharge={(newBalance) => {
              setBalance(newBalance);
              fetchPortfolio();
            }}
          />
        );

      case 'trading':
        return (
          <>
            <div style={{ marginBottom: '20px' }}>
              <StockSearch onSelectStock={handleSelectStock} />
            </div>
            
            <StockDetails symbol={symbol} />
            
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
              <div>
                <PriceChart symbol={symbol} />
              </div>
              <div>
                <TradePanel
                  symbol={symbol}
                  price={price}
                  onBuy={handleBuy}
                  onSell={handleSell}
                  loading={loading}
                />
              </div>
            </div>
            <div style={{ marginTop: '20px' }}>
              <HoldingsTable holdings={portfolio} />
            </div>
          </>
        );

      default:
        return <div>Unknown tab</div>;
    }
  };

  return (
    <div style={{ minHeight: '100vh', background: '#0a0e17' }}>
      <Navbar
        username={username}
        balance={balance}
        onLogout={logout}
        setActiveTab={setActiveTab}
        activeTab={activeTab}
      />

      <div style={{ padding: '20px 30px', maxWidth: '1200px', margin: '0 auto' }}>
        {message && (
          <div style={{
            padding: '10px',
            marginBottom: '20px',
            borderRadius: '6px',
            background: '#1a2332',
            textAlign: 'center',
            color: '#e0e6ed'
          }}>
            {message}
          </div>
        )}
        {renderContent()}
      </div>
    </div>
  );
}

export default App;
